<?php

declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';

use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Services\CatalogOptionsService;
use EventMenu\Services\PublicOrderService;
use EventMenu\Services\WaiterCallService;

$pdo=Database::connection();$token=trim((string)($_GET['t']??''));$s=$pdo->prepare('SELECT rt.*,t.name tenant_name,t.id tenant_id,t.status tenant_status,t.primary_color,t.secondary_color FROM restaurant_tables rt JOIN tenants t ON t.id=rt.tenant_id WHERE rt.qr_token=? LIMIT 1');$s->execute([$token]);$table=$s->fetch();if(!$table||$table['tenant_status']!=='active'||$table['status']==='inactive'){http_response_code(404);exit('Mesa não encontrada ou indisponível.');}$tenantId=(int)$table['tenant_id'];$unitId=$table['unit_id']?(int)$table['unit_id']:null;
$cartKey='table:'.$token;if(!isset($_SESSION['public_carts'][$cartKey])||!is_array($_SESSION['public_carts'][$cartKey]))$_SESSION['public_carts'][$cartKey]=[];$cart=&$_SESSION['public_carts'][$cartKey];$error=null;$notice=null;$self=app_url('/mesa.php?t='.urlencode($token));
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sessão expirada.';else try{$action=(string)($_POST['action']??'');
        if($action==='call'){$type=(string)($_POST['type']??'waiter');(new WaiterCallService())->createByTableToken($token,$type);$notice=match($type){'bill'=>'Conta solicitada. A equipe foi avisada.','help'=>'Pedido de ajuda enviado.','waiter'=>'Garçom chamado. A equipe foi avisada.',default=>'Solicitação enviada.'};}
        elseif($action==='add'){$id=(int)($_POST['product_id']??0);$qty=max(1,min(50,(int)($_POST['qty']??1)));$optionIds=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['option_ids']??[])),fn($v)=>$v>0)));sort($optionIds);$p=$pdo->prepare('SELECT id,unit_id FROM products WHERE id=? AND tenant_id=? AND active=1');$p->execute([$id,$tenantId]);$prod=$p->fetch();if(!$prod||($unitId&&$prod['unit_id']!==null&&(int)$prod['unit_id']!==$unitId))throw new RuntimeException('Produto indisponível.');(new CatalogOptionsService())->validateSelection($pdo,$tenantId,$id,$optionIds);$key=hash('sha256',$id.'|'.implode(',',$optionIds));if(isset($cart[$key]))$cart[$key]['qty']=min(50,(int)$cart[$key]['qty']+$qty);else$cart[$key]=['product_id'=>$id,'qty'=>$qty,'option_ids'=>$optionIds];header('Location: '.$self.'#carrinho',true,303);exit;}
        elseif($action==='qty'){$key=(string)($_POST['line_key']??'');$qty=max(0,min(50,(int)($_POST['qty']??0)));if(isset($cart[$key])){if($qty===0)unset($cart[$key]);else$cart[$key]['qty']=$qty;}header('Location: '.$self.'#carrinho',true,303);exit;}
        elseif($action==='checkout'){$result=(new PublicOrderService())->createTable($token,array_values($cart),['name'=>(string)($_POST['name']??''),'phone'=>(string)($_POST['phone']??'')]);$cart=[];header('Location: '.app_url('/pedido.php?t='.urlencode($result['public_token'])),true,303);exit;}
    }catch(Throwable$e){$error=$e->getMessage();}
}
$where='tenant_id=? AND active=1'.($unitId?' AND (unit_id IS NULL OR unit_id=?)':'');$args=$unitId?[$tenantId,$unitId]:[$tenantId];$c=$pdo->prepare('SELECT * FROM categories WHERE '.$where.' ORDER BY sort_order,name');$c->execute($args);$categories=$c->fetchAll();$p=$pdo->prepare('SELECT * FROM products WHERE '.$where.' ORDER BY featured DESC,category_id,name');$p->execute($args);$products=$p->fetchAll();$byId=[];foreach($products as$prod)$byId[(int)$prod['id']]=$prod;
$groups=[];$options=[];$productIds=array_keys($byId);if($productIds){$marks=implode(',',array_fill(0,count($productIds),'?'));$g=$pdo->prepare('SELECT * FROM product_option_groups WHERE tenant_id=? AND product_id IN ('.$marks.') AND active=1 ORDER BY product_id,sort_order,id');$g->execute([$tenantId,...$productIds]);foreach($g->fetchAll()as$r)$groups[(int)$r['product_id']][]=$r;$gids=[];foreach($groups as$rs)foreach($rs as$r)$gids[]=(int)$r['id'];if($gids){$marks=implode(',',array_fill(0,count($gids),'?'));$o=$pdo->prepare('SELECT * FROM product_options WHERE group_id IN ('.$marks.') AND active=1 ORDER BY group_id,sort_order,id');$o->execute($gids);foreach($o->fetchAll()as$r)$options[(int)$r['group_id']][]=$r;}}
$catalog=new CatalogOptionsService();$cartLines=[];$cartTotal=0;foreach($cart as$key=>$row){$id=(int)$row['product_id'];if(!isset($byId[$id]))continue;try{$sel=$catalog->validateSelection($pdo,$tenantId,$id,(array)$row['option_ids']);}catch(Throwable){continue;}$pr=$byId[$id];$base=$pr['promo_price_cents']!==null?(int)$pr['promo_price_cents']:(int)$pr['price_cents'];$unitPrice=max(0,$base+(int)$sel['delta_cents']);$line=$unitPrice*(int)$row['qty'];$cartTotal+=$line;$cartLines[]=['key'=>$key,'product'=>$pr,'qty'=>(int)$row['qty'],'options'=>$sel['options'],'unit_price'=>$unitPrice,'total'=>$line];}
$tab=$pdo->prepare('SELECT tb.id,tb.label,(SELECT COALESCE(SUM(o.total_cents),0) FROM orders o WHERE o.tab_id=tb.id AND o.status<>"cancelled") total,(SELECT COALESCE(SUM(CASE WHEN o.payment_status<>"paid" THEN o.total_cents ELSE 0 END),0) FROM orders o WHERE o.tab_id=tb.id AND o.status<>"cancelled") unpaid FROM tabs tb WHERE tb.tenant_id=? AND tb.table_id=? AND tb.status="open" LIMIT 1');$tab->execute([$tenantId,$table['id']]);$openTab=$tab->fetch();function mesa_money(int$c):string{return'R$ '.number_format($c/100,2,',','.');}$primary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($table['primary_color']??''))?$table['primary_color']:'#6d4aff';$secondary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($table['secondary_color']??''))?$table['secondary_color']:'#8b5cf6';
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="<?= Security::e($primary) ?>"><title><?= Security::e($table['tenant_name']) ?> · <?= Security::e($table['name']) ?></title><link rel="manifest" href="<?= Security::e(app_url('/manifest.webmanifest')) ?>"><link rel="stylesheet" href="<?= Security::e(app_url('/assets/app.css')) ?>?v=92legacy2"><style>:root{--table-brand:<?= Security::e($primary) ?>;--table-brand2:<?= Security::e($secondary) ?>}.table-page{background:#f6f6fb;color:#1e1f27}.shell{max-width:1160px;margin:auto;padding:18px 16px 100px}.hero{padding:28px;border-radius:26px;background:linear-gradient(135deg,var(--table-brand),var(--table-brand2));color:white;margin-bottom:18px;box-shadow:0 16px 44px #2d23672b}.call-actions{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:18px}.call-actions button{background:#ffffff1d;color:white;border:1px solid #ffffff4d;padding:12px;border-radius:13px}.layout2{display:grid;grid-template-columns:minmax(0,2fr) minmax(310px,1fr);gap:18px}.category{background:white;border:1px solid #e5e6ee;border-radius:20px;padding:18px;margin-bottom:14px}.product{display:grid;grid-template-columns:1fr auto;gap:14px;padding:14px 0;border-top:1px solid #ececf2}.product:first-of-type{border-top:0}.price{font-weight:900;color:var(--table-brand)}.option-box{background:#f7f7fb;border-radius:12px;padding:10px;margin:8px 0;font-size:.9rem}.option-row{display:flex;justify-content:space-between;padding:4px 0}.cart{position:sticky;top:14px;background:white!important;color:#222!important;border-color:#e5e6ee!important}.cart-line{padding:12px 0;border-bottom:1px solid #ececf2}.table-page input,.table-page textarea,.table-page select{background:white;color:#222;border:1px solid #dfe1ea}.table-page .muted{color:#737687}@media(max-width:820px){.layout2{grid-template-columns:1fr}.cart{position:static}.call-actions{grid-template-columns:1fr}.product{grid-template-columns:1fr}}</style></head><body class="table-page"><main class="shell"><section class="hero"><strong>EventMenu Premium</strong><p style="opacity:.85;margin-bottom:4px"><?= Security::e($table['tenant_name']) ?></p><h1 style="margin:0"><?= Security::e($table['name']) ?></h1><p>Peça pelo celular e acompanhe sua comanda.</p><?php if($openTab):?><div style="background:#fff2;padding:12px;border-radius:14px">Comanda #<?= (int)$openTab['id'] ?> · Total <?= mesa_money((int)$openTab['total']) ?> · Em aberto <?= mesa_money((int)$openTab['unpaid']) ?></div><?php endif;?><div class="call-actions"><?php foreach(['waiter'=>'Chamar garçom','bill'=>'Pedir a conta','help'=>'Preciso de ajuda']as$type=>$label):?><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="call"><input type="hidden" name="type" value="<?= $type ?>"><button><?= Security::e($label) ?></button></form><?php endforeach;?></div></section><?php if($notice):?><div class="alert ok"><?= Security::e($notice) ?></div><?php endif;?><?php if($error):?><div class="alert error"><?= Security::e($error) ?></div><?php endif;?><div class="layout2"><section><?php foreach($categories as$cat):$cp=array_values(array_filter($products,fn($p)=>(int)$p['category_id']===(int)$cat['id']));if(!$cp)continue;?><article class="category"><h2><?= Security::e($cat['name']) ?></h2><?php foreach($cp as$prod):?><div class="product"><div><strong><?= Security::e($prod['name']) ?></strong><?php if($prod['badge']):?> <span class="badge"><?= Security::e($prod['badge']) ?></span><?php endif;?><div class="muted"><?= Security::e($prod['description']??'') ?></div><?php if($prod['promo_price_cents']!==null):?><s class="muted"><?= mesa_money((int)$prod['price_cents']) ?></s> <?php endif;?><span class="price"><?= mesa_money((int)($prod['promo_price_cents']??$prod['price_cents'])) ?></span></div><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?= (int)$prod['id'] ?>"><?php foreach($groups[(int)$prod['id']]??[]as$gr):?><div class="option-box"><strong><?= Security::e($gr['name']) ?> <small class="muted"><?= $gr['min_select']?'obrigatório':'opcional' ?></small></strong><?php foreach($options[(int)$gr['id']]??[]as$op):$radio=(int)$gr['max_select']===1;?><label class="option-row"><span><input type="<?= $radio?'radio':'checkbox' ?>" <?= $radio?'name="group_'.$gr['id'].'"':'name="group_'.$gr['id'].'[]"' ?> value="<?= (int)$op['id'] ?>" onchange="syncOpts(this.form,<?= (int)$gr['id'] ?>)" <?= $radio&&(int)$gr['min_select']>0?'required':'' ?>> <?= Security::e($op['name']) ?></span><span><?= (int)$op['price_delta_cents']?(((int)$op['price_delta_cents']>0?'+ ':'- ').mesa_money(abs((int)$op['price_delta_cents']))):'' ?></span></label><?php endforeach;?></div><?php endforeach;?><div class="actions"><input type="number" name="qty" min="1" max="50" value="1" style="width:70px"><button class="primary">Adicionar</button></div></form></div><?php endforeach;?></article><?php endforeach;?></section><aside id="carrinho" class="card cart"><h2>Pedido da mesa</h2><?php if(!$cartLines):?><p class="muted">Adicione itens.</p><?php else:?><?php foreach($cartLines as$line):?><div class="cart-line"><strong><?= Security::e($line['product']['name']) ?></strong><?php if($line['options']):?><div class="muted"><?= Security::e(implode(' · ',array_column($line['options'],'name'))) ?></div><?php endif;?><div><?= mesa_money($line['total']) ?></div><form method="post" class="actions" style="margin-top:6px"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="qty"><input type="hidden" name="line_key" value="<?= Security::e($line['key']) ?>"><input type="number" name="qty" min="0" max="50" value="<?= $line['qty'] ?>" style="width:65px"><button class="secondary">Atualizar</button></form></div><?php endforeach;?><p><strong>Total <span style="float:right"><?= mesa_money($cartTotal) ?></span></strong></p><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="checkout"><label class="span-2">Seu nome <small class="muted">opcional</small><input name="name"></label><label class="span-2">Telefone <small class="muted">opcional</small><input name="phone"></label><button class="primary span-2">Enviar para a comanda</button></form><p class="muted">Depois você pode pagar online, se habilitado, ou diretamente no caixa.</p><?php endif;?></aside></div></main><script>function syncOpts(form,gid){form.querySelectorAll('[data-option-group="'+gid+'"]').forEach(i=>i.remove());form.querySelectorAll('[name^="group_'+gid+'"]:checked').forEach(v=>{const i=document.createElement('input');i.type='hidden';i.name='option_ids[]';i.value=v.value;i.dataset.optionGroup=gid;form.appendChild(i);});}if('serviceWorker'in navigator){navigator.serviceWorker.register('<?= Security::e(app_url('/sw.js')) ?>').catch(()=>{});}</script></body></html>